        min_x = min(x for x, y in piece)
        min_y = min(y for x, y in piece)
        normalized = [(x - min_x, y - min_y) for x, y in piece]
        normalized.sort()
        return tuple(normalized)

    def rotate_piece(piece):
        max_x = max(x for x, y in piece)
        return [(y, max_x - x) for x, y in piece]

    def reflect_piece(piece):
        max_y = max(y for x, y in piece)
        return [(x, max_y - y) for x, y in piece]

    def generate_all_rotations_reflections(piece):
        transformations = {normalize_piece(piece)}
        current_transforms = [piece]
        for _ in range(3):  # Rotate 3 more times
            next_transforms = [rotate_piece(p) for p in current_transforms]
            for nt in next_transforms:
                normalized = normalize_piece(nt)
                if normalized not in transformations:
                    transformations.add(normalized)
            current_transforms = next_transforms

        # Reflect and rotate
        reflected_transforms = [reflect_piece(p) for p in current_transforms]
        for rt in reflected_transforms:
            next_transforms = [rotate_piece(rt)]
            for nt in next_transforms:
                normalized = normalize_piece(nt)
                if normalized not in transformations:
