    # Try to decompose into k copies where 2 <= k <= 5
    def try_decompose(idx, used, k):
        if idx == len(pieces):
            if all(used):
                return k
            return float('inf')

        min_k = float('inf')
        piece, transformations = pieces[idx]

        for i, used_piece in enumerate(used):
            if used_piece and normalize_piece([(x + dx, y + dy) for dx, dy in piece]) in transformations:
                used[i] = True
                min_k = min(min_k, try_decompose(idx + 1, used, k))
                used[i] = False

        if k + 1 <= 5:
            used[idx] = True
            min_k = min(min_k, try_decompose(idx + 1, used, k + 1))
            used[idx] = False

        return min_k

    used_pieces = [False] * len(pieces)
    result = try_decompose(0, used_pieces, 0)

    if result == float('inf'):
        return "No solution"

    return result


