def find_polyomino(matrix):
    h, w = len(matrix), len(matrix[0])
    polyomino = set((i, j) for i in range(h) for j in range(w) if matrix[i][j] == 'X')
    if not polyomino:
        return "No solution"

    def is_connected(p1, p2):
        return abs(p1[0] - p2[0]) + abs(p1[1] - p2[1]) == 1

    def get_neighbors(p):
        return {q for q in polyomino if is_connected(p, q)}

    components = []
    visited = set()
    for p in polyomino:
        if p not in visited:
            component = set()
            queue = deque([p])
            while queue:
                node = queue.popleft()
                if node in visited:
                    continue
                visited.add(node)
                component.add(node)
                for neighbor in get_neighbors(node):
                    if neighbor not in visited:
                        queue.append(neighbor)
            components.append(component)

    if len(components) == 1 and len(polyomino) <= 4:
        return format_polyomino(matrix, [1])

    for k in range(2, 6):
        result = try_k_power(matrix, components, k)
        if result:
            return result

    return "No solution"

def try_k_power(matrix, components, k):
    h, w = len(matrix), len(matrix[0])
    smaller_polyomino = list(components[0])
    count = len(smaller_polyomino)
    if count ** k > len(matrix) * len(matrix[0]):
        return None

    def fit_at(piece, dx, dy, grid, used):
        new_piece = {(x + dx, y + dy) for x, y in piece}
        if any(x < 0 or x >= h or y < 0 or y >= w or grid[x][y] != '.' or (x, y) in used for x, y in new_piece):
            return False
        return new_piece

    def backtrack(i, grid, used):
        if i == len(components):
            return grid
        for piece_num in range(1, k + 1):
            for dx, dy in product(range(h), range(w)):
                new_piece = fit_at(smaller_polyomino, dx, dy, grid, used)
                if new_piece:
                    grid = [[grid[x][y] if (x, y) not in new_piece else str(piece_num) for y in range(w)] for x in range(h)]
                    used.update(new_piece)
                    result = backtrack(i + 1, grid, used)
                    if result:
                        return result
                    used.difference_update(new_piece)
        return None

    initial_grid = [['.' for _ in range(w)] for _ in range(h)]
    return backtrack(0, initial_grid, set())

